p = "AGTTTTTAG"
g = ""
def patternIndex(genome: str, pattern: str) -> list[int]:
    x = 0
    patternI = []
    while x < (len(genome)-len(pattern))+1:
        if(genome[x:x+len(pattern)]) == pattern:
            patternI.append(x)
        x = x+1

    #answer = ""
    #for item in patternI:
        #answer += str(item) + " "
    return patternI


